package orchestrator
import("errors";"os";"strings";"testing";"time";"github.com/madkoding/kitties/internal/config";"github.com/madkoding/kitties/internal/oauth")
func TestLexOpenGitHubPersistentPairRestartAndAtomicRotation(t *testing.T){for _,public:=range []bool{false,true}{t.Run(map[bool]string{false:"web",true:"device"}[public],func(t *testing.T){cfg:=testConfig(t);cfg.Connectors=map[string]config.Connector{};m,e:=New(cfg);if e!=nil{t.Fatal(e)};name,app,creds:=lexopenNewAliasFixture("github");app.Settings["oauth_lexopen_github_refresh"]="v1";creds.RefreshToken="fixture-github-refresh";creds.Expiry=time.Now().Add(8*time.Hour).Truncate(time.Second);if public{app.ClientSecret="";app.Settings["oauth_public_client"]="true"};if e=m.OAuth().ImportCredentials(name,app,creds);e!=nil{t.Fatal(e)};again,e:=New(cfg);if e!=nil{t.Fatal(e)};a,_:=again.OAuthApp(name);c,_:=again.OAuthCredentials(name);if a.Settings["oauth_lexopen_github_refresh"]!="v1"||a.Settings["oauth_public_client"]!=app.Settings["oauth_public_client"]||a.ClientSecret!=app.ClientSecret||!lexopenGHEqual(c,creds){t.Fatal("restart lost exact app+pair")};next:=creds;next.AccessToken="fixture-github-new";next.RefreshToken="fixture-github-rotated";if e=again.SaveOAuthCredentials(name,next);e!=nil{t.Fatal(e)};third,e:=New(cfg);if e!=nil{t.Fatal(e)};c,_=third.OAuthCredentials(name);if !lexopenGHEqual(c,next){t.Fatal("rotation not durable")};if e=third.RemoveConnector(name);e!=nil{t.Fatal(e)};if e=third.SaveOAuthCredentials(name,next);!errors.Is(e,ErrNotFound){t.Fatal("refresh recreated removed alias")}})}}
func TestLexOpenGitHubPersistentRotationFailurePreservesPair(t *testing.T){cfg:=testConfig(t);m,e:=New(cfg);if e!=nil{t.Fatal(e)};name,app,c:=lexopenNewAliasFixture("github");app.Settings["oauth_lexopen_github_refresh"]="v1";c.RefreshToken="fixture-github-refresh";if e=m.OAuth().ImportCredentials(name,app,c);e!=nil{t.Fatal(e)};before,_:=os.ReadFile(m.settingsPath());if e=os.Remove(m.settingsPath());e!=nil{t.Fatal(e)};if e=os.Mkdir(m.settingsPath(),0700);e!=nil{t.Fatal(e)};next:=c;next.AccessToken="fixture-github-new";next.RefreshToken="fixture-github-rotated";e=m.SaveOAuthCredentials(name,next);after,_:=m.OAuthCredentials(name);if e==nil||!lexopenGHEqual(after,c)||strings.Contains(e.Error(),next.RefreshToken){t.Fatal("failed rotation changed live pair or leaked")};if len(before)==0{t.Fatal("no persisted fixture")}}

func TestLexOpenGitHubPersistentExplicitStaticReplacementForgetsRefresh(t *testing.T){cfg:=testConfig(t);m,e:=New(cfg);if e!=nil{t.Fatal(e)};name,app,c:=lexopenNewAliasFixture("github");app.Settings["oauth_lexopen_github_refresh"]="v1";c.RefreshToken="fixture-github-refresh";if e=m.OAuth().ImportCredentials(name,app,c);e!=nil{t.Fatal(e)};if e=m.SetConnector(name,config.Connector{Kind:"github",Settings:map[string]string{"token":"fixture-static-new"}},ConnectorChange{Clear:[]string{SignOut}});e!=nil{t.Fatal(e)};got,_:=m.OAuthCredentials(name);a,_:=m.OAuthApp(name);if got.RefreshToken!=""||got.AccessToken!=""||a.Settings["oauth_lexopen_github_refresh"]!=""||m.OAuth().Due(name){t.Fatal("explicit replacement retained old renewable authorization")}}

func lexopenGHEqual(a,b oauth.Credentials)bool{return a.AccessToken==b.AccessToken&&a.RefreshToken==b.RefreshToken&&a.Account==b.Account&&a.Expiry.Equal(b.Expiry)}
